from __future__ import annotations

import argparse
import json
from pathlib import Path

import cadquery as cq

CAD_SPEC = json.loads('{\n  "schema_version": "1.0",\n  "name": "promptcad-enclosure",\n  "source_prompt": "做一個94x58x22mm外殼，壁厚2mm，+Y面一個14x8mm矩形開口，中心x=25mm、z=9mm",\n  "unit": "mm",\n  "material": null,\n  "base": {\n    "kind": "enclosure",\n    "length": 94.0,\n    "width": 58.0,\n    "height": 22.0,\n    "wall_thickness": 2.0\n  },\n  "holes": [],\n  "cutouts": [\n    {\n      "kind": "rectangular_cutout",\n      "face": "positive_y",\n      "x": 25.0,\n      "y": 0.0,\n      "z": 9.0,\n      "width": 14.0,\n      "height": 8.0\n    }\n  ],\n  "fillets": [],\n  "chamfers": [],\n  "assumptions": [],\n  "notes": [],\n  "planner": {\n    "planner": "rule",\n    "confidence": 0.92,\n    "review_required": false\n  }\n}')


def build():
    warnings = []
    outer = cq.Workplane('XY').box(94, 58, 22, centered=(True, True, False))
    inner = cq.Workplane('XY').box(90, 54, 20.2, centered=(True, True, False)).translate((0, 0, 2))
    result = outer.cut(inner)
    cutout_0 = cq.Workplane('XY').box(14, 2.4, 8, centered=(True, True, True)).translate((25, 28, 9))
    result = result.cut(cutout_0)
    return result, warnings


def export_all(result, output_dir: Path, formats: set[str], warnings: list[str]):
    output_dir.mkdir(parents=True, exist_ok=True)
    if 'step' in formats:
        result.export(str(output_dir / 'model.step'))
    if 'stl' in formats:
        result.export(str(output_dir / 'model.stl'), tolerance=0.05, angularTolerance=0.1)
    if 'svg' in formats:
        result.export(str(output_dir / 'model.svg'), opt={
            'width': 900, 'height': 650, 'marginLeft': 20, 'marginTop': 20,
            'showAxes': False, 'projectionDir': (1, -1, 0.75),
            'showHidden': True, 'strokeWidth': 0.7,
        })
    if 'dxf' in formats:
        try:
            section = result.section(11)
            section.export(str(output_dir / 'model.dxf'), opt={'approx': 'arc', 'tolerance': 0.01})
        except Exception as exc:
            warnings.append('DXF section export skipped: ' + str(exc))
    (output_dir / 'render-warnings.json').write_text(
        json.dumps(warnings, ensure_ascii=False, indent=2), encoding='utf-8'
    )


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--output-dir', default='.')
    parser.add_argument('--formats', nargs='*', default=['step', 'stl', 'dxf', 'svg'])
    args = parser.parse_args()
    result, warnings = build()
    export_all(result, Path(args.output_dir), set(args.formats), warnings)


if __name__ == '__main__':
    main()
